/**
 * Shared core type contracts for an Apple-inspired blog website.
 * These types define the canonical data shapes for site configuration,
 * navigation, hero content, articles, authors, footer links, animation,
 * and responsive layout breakpoints.
 */

/**
 * Supported content locales for the site.
 */
export type Locale = 'zh-CN' | 'en-US' | 'ja-JP' | 'ko-KR' | 'fr-FR' | 'de-DE' | 'es-ES';

/**
 * Visual theme variants used across the site.
 */
export type ThemeMode = 'light' | 'dark' | 'system';

/**
 * Semantic page section identifiers.
 */
export type SectionId = 'home' | 'articles' | 'about' | 'archive' | 'contact' | 'search';

/**
 * Navigation link target behavior.
 */
export type LinkTarget = '_self' | '_blank' | '_parent' | '_top';

/**
 * Footer link grouping categories.
 */
export type FooterLinkGroup = 'product' | 'company' | 'resources' | 'legal' | 'social';

/**
 * Article content status.
 */
export type ArticleStatus = 'draft' | 'published' | 'archived';

/**
 * Article reading complexity level.
 */
export type ReadingLevel = 'beginner' | 'intermediate' | 'advanced';

/**
 * Supported media aspect ratios for hero/cover visuals.
 */
export type MediaAspectRatio = '1:1' | '4:3' | '16:9' | '3:2' | '21:9';

/**
 * Common animation easing tokens.
 */
export type Easing = 'linear' | 'ease' | 'ease-in' | 'ease-out' | 'ease-in-out' | 'spring';

/**
 * Responsive layout breakpoints.
 */
export type Breakpoint = 'xs' | 'sm' | 'md' | 'lg' | 'xl' | '2xl';

/**
 * Standardized route path for internal navigation.
 */
export type RoutePath = `/${string}`;

/**
 * External or internal URL value.
 */
export type Url = string;

/**
 * Unique identifier used throughout content and layout entities.
 */
export type EntityId = string;

/**
 * Generic ISO 8601 datetime string.
 */
export type ISODateTimeString = string;

/**
 * Generic ISO 8601 date string.
 */
export type ISODateString = string;

/**
 * Site-wide configuration shared across modules.
 */
export interface SiteConfig {
  /** Site name displayed in the header, metadata, and footer. */
  readonly name: string;
  /** Short brand tagline used in hero and metadata. */
  readonly tagline: string;
  /** Optional site description for SEO and social sharing. */
  readonly description?: string;
  /** Primary locale for content and formatting. */
  readonly locale: Locale;
  /** Default theme preference. */
  readonly themeMode: ThemeMode;
  /** Base URL of the website, including protocol. */
  readonly siteUrl: Url;
  /** Default logo or mark asset URL. */
  readonly logoUrl?: Url;
  /** Default Open Graph image URL. */
  readonly ogImageUrl?: Url;
  /** Copyright owner text. */
  readonly copyright?: string;
}

/**
 * Navigation item used in the top navigation and mobile menu.
 */
export interface NavigationItem {
  /** Unique item id. */
  readonly id: EntityId;
  /** Display label. */
  readonly label: string;
  /** Target path or URL. */
  readonly href: RoutePath | Url;
  /** Whether the item is currently active. */
  readonly active?: boolean;
  /** Open target behavior. */
  readonly target?: LinkTarget;
  /** Optional icon name or asset reference. */
  readonly icon?: string;
  /** Optional section identifier for in-page anchors. */
  readonly sectionId?: SectionId;
}

/**
 * Hero block content for the landing page.
 */
export interface HeroBlock {
  /** Eyebrow text above the main title. */
  readonly eyebrow?: string;
  /** Main title. */
  readonly title: string;
  /** Supporting description text. */
  readonly description: string;
  /** Primary call-to-action label. */
  readonly primaryCtaLabel?: string;
  /** Primary call-to-action link. */
  readonly primaryCtaHref?: RoutePath | Url;
  /** Secondary call-to-action label. */
  readonly secondaryCtaLabel?: string;
  /** Secondary call-to-action link. */
  readonly secondaryCtaHref?: RoutePath | Url;
  /** Optional hero media asset. */
  readonly mediaUrl?: Url;
  /** Media aspect ratio for the hero visual. */
  readonly mediaAspectRatio?: MediaAspectRatio;
}

/**
 * Author profile information.
 */
export interface AuthorInfo {
  /** Author id. */
  readonly id: EntityId;
  /** Author display name. */
  readonly name: string;
  /** Author short bio. */
  readonly bio?: string;
  /** Author avatar image URL. */
  readonly avatarUrl?: Url;
  /** Author profile page URL. */
  readonly profileUrl?: RoutePath | Url;
  /** Social or portfolio links. */
  readonly socialLinks?: ReadonlyArray<SocialLink>;
}

/**
 * Social link for authors or site-wide brand accounts.
 */
export interface SocialLink {
  /** Platform name. */
  readonly platform: string;
  /** Destination URL. */
  readonly href: Url;
  /** Open target behavior. */
  readonly target?: LinkTarget;
  /** Optional accessible label. */
  readonly ariaLabel?: string;
}

/**
 * Article summary used in lists, cards, and featured sections.
 */
export interface ArticleSummary {
  /** Article id. */
  readonly id: EntityId;
  /** Article slug used in URLs. */
  readonly slug: string;
  /** Article title. */
  readonly title: string;
  /** Short teaser or excerpt. */
  readonly excerpt: string;
  /** One-line summary or subtitle. */
  readonly subtitle?: string;
  /** Cover image URL. */
  readonly coverImageUrl?: Url;
  /** Cover image alt text. */
  readonly coverImageAlt?: string;
  /** Article author. */
  readonly author: AuthorInfo;
  /** Publish date. */
  readonly publishedAt: ISODateTimeString;
  /** Last update date. */
  readonly updatedAt?: ISODateTimeString;
  /** Estimated reading time in minutes. */
  readonly readingTimeMinutes?: number;
  /** Content tags. */
  readonly tags?: ReadonlyArray<string>;
  /** Featured flag for homepage selection. */
  readonly featured?: boolean;
  /** Publication status. */
  readonly status?: ArticleStatus;
  /** Reading level. */
  readonly readingLevel?: ReadingLevel;
}

/**
 * Rich article detail information.
 */
export interface ArticleDetail extends ArticleSummary {
  /** Full article HTML or rendered rich text content. */
  readonly content: string;
  /** Additional SEO description. */
  readonly seoDescription?: string;
  /** Canonical URL for the article. */
  readonly canonicalUrl?: Url;
  /** Related article ids. */
  readonly relatedArticleIds?: ReadonlyArray<EntityId>;
  /** Table of contents items. */
  readonly tableOfContents?: ReadonlyArray<TableOfContentsItem>;
}

/**
 * Table of contents item for article detail pages.
 */
export interface TableOfContentsItem {
  /** Anchor id for the heading. */
  readonly id: string;
  /** Heading label. */
  readonly label: string;
  /** Heading level from 1 to 6. */
  readonly level: 1 | 2 | 3 | 4 | 5 | 6;
}

/**
 * Footer link definition.
 */
export interface FooterLink {
  /** Link id. */
  readonly id: EntityId;
  /** Display label. */
  readonly label: string;
  /** Link destination. */
  readonly href: RoutePath | Url;
  /** Link grouping for layout. */
  readonly group: FooterLinkGroup;
  /** Open target behavior. */
  readonly target?: LinkTarget;
  /** Optional accessibility label. */
  readonly ariaLabel?: string;
}

/**
 * Animation configuration shared by layout and interaction modules.
 */
export interface AnimationConfig {
  /** Enable or disable motion globally. */
  readonly enabled: boolean;
  /** Base duration in milliseconds. */
  readonly durationMs: number;
  /** Delay before animation start in milliseconds. */
  readonly delayMs?: number;
  /** Easing token. */
  readonly easing: Easing;
  /** Entrance animation offset in pixels. */
  readonly translateY?: number;
  /** Entrance animation offset in pixels on the x-axis. */
  readonly translateX?: number;
  /** Scale transform during entrance. */
  readonly scale?: number;
  /** Opacity starting value. */
  readonly initialOpacity?: number;
  /** Stagger delay between items in milliseconds. */
  readonly staggerMs?: number;
  /** Repeat count for looping animations. */
  readonly repeat?: number;
}

/**
 * Responsive layout breakpoint definition.
 */
export interface LayoutBreakpoint {
  /** Breakpoint key. */
  readonly name: Breakpoint;
  /** Minimum viewport width in pixels. */
  readonly minWidthPx: number;
  /** Optional maximum viewport width in pixels. */
  readonly maxWidthPx?: number;
  /** Grid columns used at this breakpoint. */
  readonly columns?: number;
  /** Horizontal content padding in pixels. */
  readonly gutterPx?: number;
}

/**
 * Layout system contract containing all breakpoints.
 */
export interface LayoutSystem {
  /** Ordered list of breakpoints from small to large. */
  readonly breakpoints: ReadonlyArray<LayoutBreakpoint>;
  /** Maximum content width in pixels. */
  readonly maxContentWidthPx: number;
  /** Base page horizontal padding in pixels. */
  readonly pagePaddingPx: number;
  /** Default column gap in pixels. */
  readonly columnGapPx?: number;
  /** Default row gap in pixels. */
  readonly rowGapPx?: number;
}

/**
 * Generic key-value metadata map.
 */
export type MetadataMap = Readonly<Record<string, string | number | boolean | null | undefined>>;

/**
 * Generic paginated result contract.
 */
export interface PaginatedResult<T> {
  /** Items for the current page. */
  readonly items: ReadonlyArray<T>;
  /** Current page number, starting at 1. */
  readonly page: number;
  /** Page size. */
  readonly pageSize: number;
  /** Total number of items. */
  readonly totalItems: number;
  /** Total pages. */
  readonly totalPages: number;
}

/**
 * Generic result state for loading and error handling.
 */
export type AsyncState<T> =
  | { readonly status: 'idle' | 'loading'; readonly data?: undefined; readonly error?: undefined }
  | { readonly status: 'success'; readonly data: T; readonly error?: undefined }
  | { readonly status: 'error'; readonly data?: undefined; readonly error: Error };

/**
 * Shared site content bundle used by page shells and data loaders.
 */
export interface SiteContentBundle {
  /** Site configuration. */
  readonly config: SiteConfig;
  /** Navigation items. */
  readonly navigation: ReadonlyArray<NavigationItem>;
  /** Home hero content. */
  readonly hero?: HeroBlock;
  /** Featured articles. */
  readonly featuredArticles?: ReadonlyArray<ArticleSummary>;
  /** Footer links. */
  readonly footerLinks?: ReadonlyArray<FooterLink>;
  /** Animation settings. */
  readonly animation?: AnimationConfig;
  /** Layout settings. */
  readonly layout?: LayoutSystem;
}

/**
 * Props contract for a page section component.
 */
export interface SectionProps<TContent> {
  /** Section identifier. */
  readonly id: SectionId;
  /** Section content model. */
  readonly content: TContent;
  /** Optional CSS class names. */
  readonly className?: string;
  /** Optional metadata map for analytics or testing. */
  readonly metadata?: MetadataMap;
}

/**
 * Nullable helper type alias for optional domain values.
 */
export type Nullable<T> = T | null;

/**
 * Optional helper type alias for domain values that may be omitted. */
export type Optional<T> = T | undefined;

/**
 * Deep readonly helper for immutable shared contracts. */
export type DeepReadonly<T> = T extends (...args: unknown[]) => unknown
  ? T
  : T extends ReadonlyArray<infer U>
    ? ReadonlyArray<DeepReadonly<U>>
    : T extends object
      ? { readonly [K in keyof T]: DeepReadonly<T[K]> }
      : T;

import type {
  ArticleStatus,
  EntityId,
  FooterLinkGroup,
  ISODateString,
  Locale,
  NavigationItem,
  RoutePath,
  SectionId,
  SiteConfig,
  Url,
} from './types';

/**
 * Hero content displayed on the home page.
 */
export interface HeroContent {
  /** Main headline. */
  readonly title: string;
  /** Supporting description. */
