  /** Primary call-to-action text. */
  readonly primaryActionLabel: string;
  /** Primary call-to-action target. */
  readonly primaryActionHref: RoutePath | Url;
  /** Secondary call-to-action text. */
  readonly secondaryActionLabel: string;
  /** Secondary call-to-action target. */
  readonly secondaryActionHref: RoutePath | Url;
}

/**
 * Author profile metadata.
 */
export interface AuthorProfile {
  /** Unique author identifier. */
  readonly id: EntityId;
  /** Display name. */
  readonly name: string;
  /** Short biography. */
  readonly bio: string;
  /** Avatar image URL. */
  readonly avatarUrl: Url;
  /** Personal website or profile URL. */
  readonly websiteUrl?: Url;
}

/**
 * Blog article content model.
 */
export interface Article {
  /** Unique article identifier. */
  readonly id: EntityId;
  /** URL slug used to resolve detail pages. */
  readonly slug: string;
  /** Title shown in cards and detail pages. */
  readonly title: string;
  /** Summary for listings and previews. */
  readonly excerpt: string;
  /** Long-form body content. */
  readonly content: string;
  /** Cover image URL. */
  readonly coverImageUrl: Url;
  /** Publishing date. */
  readonly publishedAt: ISODateString;
  /** Current publication status. */
  readonly status: ArticleStatus;
  /** Whether the article is featured. */
  readonly featured: boolean;
  /** Recommended reading time in minutes. */
  readonly readingTimeMinutes: number;
  /** Brief article introduction or headline line. */
  readonly summary: string;
  /** Associated author. */
  readonly author: AuthorProfile;
  /** Article topic tags. */
  readonly tags: readonly string[];
  /** Related article ids. */
  readonly relatedArticleIds: readonly EntityId[];
}

/**
 * Footer link entry.
 */
export interface FooterLink {
  /** Link group. */
  readonly group: FooterLinkGroup;
  /** Display label. */
  readonly label: string;
  /** Link target. */
  readonly href: RoutePath | Url;
}

/**
 * Static content container for the blog website.
 */
export interface ContentLayer {
  /** Site configuration. */
  readonly site: SiteConfig;
  /** Top navigation items. */
  readonly navigation: readonly NavigationItem[];
  /** Home hero content. */
  readonly hero: HeroContent;
  /** Featured articles shown on the home page. */
  readonly featuredArticles: readonly Article[];
  /** Full article list. */
  readonly articles: readonly Article[];
  /** Author introduction content. */
  readonly author: AuthorProfile;
  /** Footer links. */
  readonly footerLinks: readonly FooterLink[];
}

