/**
 * Find an article by slug.
 *
 * @param slug - Article slug.
 * @returns The matching article, or undefined when not found.
 */
export function getArticleBySlug(slug: string | null | undefined): Article | undefined {
  if (typeof slug !== 'string' || slug.trim().length === 0) {
    return undefined;
  }
  return articles.find((article: Article) => article.slug === slug.trim());
}

/**
 * Get all featured articles.
 *
 * @returns Featured articles in their original order.
 */
export function getFeaturedArticles(): readonly Article[] {
  return featuredArticles;
}

/**
 * Get navigation items for a specific locale.
 *
 * @param _locale - Locale value kept for future localization expansion.
 * @returns Navigation items.
 */
export function getNavigation(_locale: Locale): readonly NavigationItem[] {
  return navigation;
}

/**
 * Get recommended articles for a given article slug.
 *
 * @param slug - Current article slug.
 * @param limit - Maximum number of recommended articles to return.
 * @returns Recommended articles excluding the source article.
 */
export function getRecommendedArticles(slug: string | null | undefined, limit: number = 3): readonly Article[] {
  const sourceArticle: Article | undefined = getArticleBySlug(slug);
  const safeLimit: number = Number.isFinite(limit) && limit > 0 ? Math.floor(limit) : 3;
  const sourceRelatedIds: readonly EntityId[] = sourceArticle?.relatedArticleIds ?? [];
  const candidates: Article[] = articles.filter((article: Article) => article.slug !== sourceArticle?.slug);

  const prioritized: Article[] = candidates.filter((article: Article) => sourceRelatedIds.includes(article.id));
  const fallback: Article[] = candidates.filter((article: Article) => !sourceRelatedIds.includes(article.id));

  return [...prioritized, ...fallback].slice(0, safeLimit);
}

