/**
 * Theme and design tokens for the site.
 *
 * Provides a clean, premium visual system with generous whitespace,
 * strong title hierarchy, refined typography, and responsive helpers.
 */
import type { ThemeMode } from './types';

/**
 * Supported layout breakpoint names.
 */
export type BreakpointName = 'xs' | 'sm' | 'md' | 'lg' | 'xl' | '2xl';

/**
 * Supported text style roles.
 */
export type TextStyleRole = 'title' | 'subtitle' | 'body' | 'caption' | 'overline';

/**
 * Supported card elevation levels.
 */
export type CardElevation = 'none' | 'sm' | 'md' | 'lg';

/**
 * Design token set for spacing, color, typography, and layout.
 */
export interface Theme {
  /** Color tokens. */
  readonly colors: {
    readonly background: {
      readonly base: string;
      readonly subtle: string;
      readonly elevated: string;
      readonly inverse: string;
    };
    readonly foreground: {
      readonly primary: string;
      readonly secondary: string;
      readonly tertiary: string;
      readonly muted: string;
      readonly inverse: string;
    };
    readonly accent: {
      readonly primary: string;
      readonly primaryHover: string;
      readonly secondary: string;
      readonly success: string;
      readonly warning: string;
      readonly danger: string;
    };
    readonly border: {
      readonly subtle: string;
      readonly default: string;
      readonly strong: string;
      readonly divider: string;
    };
    readonly overlay: {
      readonly scrim: string;
      readonly glass: string;
    };
  };
  /** Font family tokens. */
  readonly fonts: {
    readonly sans: string;
    readonly serif: string;
    readonly mono: string;
  };
  /** Typography scale tokens. */
  readonly typography: {
    readonly display: { readonly fontSize: string; readonly lineHeight: number; readonly fontWeight: number; readonly letterSpacing: string };
    readonly h1: { readonly fontSize: string; readonly lineHeight: number; readonly fontWeight: number; readonly letterSpacing: string };
    readonly h2: { readonly fontSize: string; readonly lineHeight: number; readonly fontWeight: number; readonly letterSpacing: string };
    readonly h3: { readonly fontSize: string; readonly lineHeight: number; readonly fontWeight: number; readonly letterSpacing: string };
    readonly body: { readonly fontSize: string; readonly lineHeight: number; readonly fontWeight: number; readonly letterSpacing: string };
    readonly bodySmall: { readonly fontSize: string; readonly lineHeight: number; readonly fontWeight: number; readonly letterSpacing: string };
    readonly caption: { readonly fontSize: string; readonly lineHeight: number; readonly fontWeight: number; readonly letterSpacing: string };
    readonly overline: { readonly fontSize: string; readonly lineHeight: number; readonly fontWeight: number; readonly letterSpacing: string; readonly textTransform: 'uppercase' };
  };
  /** Spacing scale tokens. */
  readonly spacing: {
    readonly 0: string;
    readonly 1: string;
    readonly 2: string;
    readonly 3: string;
    readonly 4: string;
    readonly 5: string;
    readonly 6: string;
    readonly 8: string;
    readonly 10: string;
    readonly 12: string;
    readonly 16: string;
    readonly 20: string;
    readonly 24: string;
    readonly 32: string;
    readonly 40: string;
    readonly 48: string;
    readonly 64: string;
  };
  /** Radius tokens. */
  readonly radii: {
    readonly none: string;
    readonly sm: string;
    readonly md: string;
    readonly lg: string;
    readonly xl: string;
    readonly full: string;
  };
  /** Shadow tokens. */
  readonly shadows: {
    readonly none: string;
    readonly sm: string;
    readonly md: string;
    readonly lg: string;
    readonly focus: string;
  };
  /** Background gradient tokens. */
  readonly gradients: {
    readonly hero: string;
    readonly section: string;
    readonly card: string;
  };
  /** Divider tokens. */
  readonly dividers: {
    readonly subtle: string;
    readonly default: string;
    readonly strong: string;
  };
  /** Container width tokens. */
  readonly container: {
    readonly maxWidth: string;
    readonly contentWidth: string;
    readonly wideWidth: string;
    readonly paddingX: string;
  };
  /** Responsive breakpoint tokens. */
  readonly breakpoints: Record<BreakpointName, number>;
}

/**
 * Full theme object used by layout and component rendering.
 */
export const theme: Theme = {
