  },
  breakpoints: {
    xs: 0,
    sm: 576,
    md: 768,
    lg: 1024,
    xl: 1280,
    '2xl': 1536,
  },
};

/**
 * Returns a font style object for a title role.
 *
 * @param level - Title level to use.
 * @returns A CSS-compatible typography style object.
 */
export function getTitleStyle(level: 'display' | 'h1' | 'h2' | 'h3' = 'h1'): Record<string, string | number> {
  return {
    fontFamily: theme.fonts.sans,
    fontSize: theme.typography[level].fontSize,
    lineHeight: theme.typography[level].lineHeight,
    fontWeight: theme.typography[level].fontWeight,
    letterSpacing: theme.typography[level].letterSpacing,
    color: theme.colors.foreground.primary,
  };
}

/**
 * Returns a font style object for body text.
 *
 * @param size - Body size variant.
 * @returns A CSS-compatible typography style object.
 */
export function getBodyStyle(size: 'body' | 'bodySmall' | 'caption' = 'body'): Record<string, string | number> {
  return {
    fontFamily: theme.fonts.sans,
    fontSize: theme.typography[size].fontSize,
    lineHeight: theme.typography[size].lineHeight,
    fontWeight: theme.typography[size].fontWeight,
    letterSpacing: theme.typography[size].letterSpacing,
    color: size === 'caption' ? theme.colors.foreground.tertiary : theme.colors.foreground.secondary,
  };
}

/**
 * Returns card styling for a given elevation.
 *
 * @param elevation - Shadow depth for the card.
 * @returns A CSS-compatible style object.
 */
export function getCardStyle(elevation: CardElevation = 'md'): Record<string, string> {
  const shadowMap: Record<CardElevation, string> = {
    none: theme.shadows.none,
    sm: theme.shadows.sm,
    md: theme.shadows.md,
    lg: theme.shadows.lg,
  };

  return {
    background: theme.gradients.card,
    color: theme.colors.foreground.primary,
    border: theme.dividers.subtle,
    borderRadius: theme.radii.lg,
    boxShadow: shadowMap[elevation],
    backdropFilter: 'saturate(180%) blur(20px)',
  };
}

/**
 * Returns whether the viewport width matches at least the specified breakpoint.
 *
 * @param width - Current viewport width in pixels.
 * @param breakpoint - Minimum breakpoint name.
 * @returns True when width is greater than or equal to the breakpoint.
 */
export function isBreakpointUp(width: number | null | undefined, breakpoint: BreakpointName): boolean {
  if (width === null || width === undefined || Number.isNaN(width)) {
    return false;
  }
  return width >= theme.breakpoints[breakpoint];
}

/**
 * Returns whether the viewport width matches below the specified breakpoint.
 *
 * @param width - Current viewport width in pixels.
 * @param breakpoint - Exclusive upper breakpoint name.
 * @returns True when width is less than the breakpoint.
 */
export function isBreakpointDown(width: number | null | undefined, breakpoint: BreakpointName): boolean {
  if (width === null || width === undefined || Number.isNaN(width)) {
    return false;
  }
  return width < theme.breakpoints[breakpoint];
}

/**
 * Returns a responsive container style.
 *
 * @param wide - Whether to use the wider page shell.
 * @returns A CSS-compatible style object.
 */
export function getContainerStyle(wide: boolean = false): Record<string, string> {
  return {
    width: '100%',
    maxWidth: wide ? theme.container.wideWidth : theme.container.maxWidth,
    paddingLeft: theme.container.paddingX,
    paddingRight: theme.container.paddingX,
    marginLeft: 'auto',
    marginRight: 'auto',
  };
}

/**
 * Returns a semantic text style by role.
 *
 * @param role - Text style role.
 * @returns A CSS-compatible style object.
 */
export function getTextStyle(role: TextStyleRole): Record<string, string | number> {
  switch (role) {
    case 'title':
      return getTitleStyle('h1');
    case 'subtitle':
      return getTitleStyle('h3');
    case 'body':
      return getBodyStyle('body');
    case 'caption':
      return getBodyStyle('caption');
    case 'overline':
      return {
        fontFamily: theme.fonts.sans,
        fontSize: theme.typography.overline.fontSize,
        lineHeight: theme.typography.overline.lineHeight,
        fontWeight: theme.typography.overline.fontWeight,
        letterSpacing: theme.typography.overline.letterSpacing,
        textTransform: theme.typography.overline.textTransform,
        color: theme.colors.foreground.tertiary,
      };
    default: {
      const exhaustiveCheck: never = role;
      return exhaustiveCheck;
    }
  }
}

/**
 * Returns a divider style string for the requested strength.
 *
 * @param strength - Divider emphasis level.
 * @returns A CSS border declaration string.
 */
export function getDividerStyle(strength: 'subtle' | 'default' | 'strong' = 'subtle'): string {
  return theme.dividers[strength];
}

/**
 * Returns a background gradient token by name.
 *
 * @param name - Gradient token name.
 * @returns A CSS gradient string.
 */
export function getGradient(name: 'hero' | 'section' | 'card' = 'hero'): string {
  return theme.gradients[name];
}

/**
 * Returns a spacing token value.
 *
 * @param step - The spacing step key.
 * @returns The spacing value in pixels.
 */
export function getSpacing(step: keyof Theme['spacing']): string {
  return theme.spacing[step];
}

/**
 * Returns the closest breakpoint name for a viewport width.
 *
 * @param width - Viewport width in pixels.
 * @returns The matching breakpoint or null when width is invalid.
 */
export function getBreakpointName(width: number | null | undefined): BreakpointName | null {
  if (width === null || width === undefined || Number.isNaN(width)) {
    return null;
  }

  if (width >= theme.breakpoints['2xl']) return '2xl';
  if (width >= theme.breakpoints.xl) return 'xl';
  if (width >= theme.breakpoints.lg) return 'lg';
  if (width >= theme.breakpoints.md) return 'md';
  if (width >= theme.breakpoints.sm) return 'sm';
  return 'xs';
}

import type { BreakpointName } from './theme';

/**
 * Reduced-motion preference state.
 */
export type MotionPreference = 'system' | 'reduce' | 'no-preference';

/**
 * Animation timing token names.
 */
export type AnimationDurationName = 'fast' | 'normal' | 'slow' | 'slower';

/**
 * Animation easing token names.
 */
export type AnimationEasingName = 'standard' | 'decelerate' | 'accelerate' | 'sharp';

/**
 * Transition delay step token names.
 */
export type StaggerStepName = 'none' | 'xs' | 'sm' | 'md' | 'lg';

/**
 * Viewport trigger configuration for scroll-driven animations.
 */
export interface ViewportTrigger {
  /**
   * Intersection threshold used to trigger the animation.
   */
  readonly amount: number;

  /**
   * Root margin string for the viewport observer.
   */
  readonly margin: string;

  /**
   * Whether the animation should trigger only once.
   */
  readonly once: boolean;
}

/**
 * Unified animation token contract.
 */
export interface AnimationTokens {
  /**
   * Motion preference used to resolve reduced-motion fallback behavior.
   */
  readonly motionPreference: MotionPreference;

  /**
   * Standard durations in milliseconds.
   */
  readonly duration: Readonly<Record<AnimationDurationName, number>>;

  /**
   * Standard easing curves.
   */
  readonly easing: Readonly<Record<AnimationEasingName, string>>;

  /**
   * Stagger delay steps in milliseconds.
   */
  readonly stagger: Readonly<Record<StaggerStepName, number>>;

  /**
   * Viewport trigger defaults.
   */
  readonly viewport: ViewportTrigger;
}

/**
 * Minimal animation state contract compatible with layout/component reuse.
 */
export interface AnimationState {
  /**
   * Initial hidden state.
   */
  readonly initial: Record<string, string | number>;

  /**
   * Visible target state.
   */
  readonly animate: Record<string, string | number>;

  /**
   * Exit target state.
   */
  readonly exit?: Record<string, string | number>;

  /**
   * Transition configuration.
   */
  readonly transition: Readonly<Record<string, string | number | boolean | undefined>>;

  /**
   * Viewport trigger options when used for scroll entry.
   */
  readonly viewport?: ViewportTrigger;

  /**
   * Hover interaction state.
   */
  readonly whileHover?: Record<string, string | number>;
}

/**
 * Internal reduced-motion detection key.
 */
const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

/**
 * Default animation tokens used across the site.
 */
export const animationTokens: AnimationTokens = Object.freeze({
  motionPreference: 'system',
  duration: Object.freeze({
    fast: 180,
    normal: 280,
    slow: 420,
    slower: 560,
  }),
  easing: Object.freeze({
    standard: 'cubic-bezier(0.2, 0, 0, 1)',
    decelerate: 'cubic-bezier(0, 0, 0.2, 1)',
    accelerate: 'cubic-bezier(0.4, 0, 1, 1)',
    sharp: 'cubic-bezier(0.4, 0, 0.6, 1)',
  }),
  stagger: Object.freeze({
    none: 0,
    xs: 40,
    sm: 80,
    md: 120,
    lg: 160,
  }),
  viewport: Object.freeze({
    amount: 0.18,
    margin: '0px 0px -12% 0px',
    once: true,
  }),
});

/**
 * Resolves whether reduced motion should be applied.
 *
 * @param preference - Preferred motion setting.
 * @returns True when motion should be minimized.
 */
export function isReducedMotion(preference: MotionPreference = animationTokens.motionPreference): boolean {
  if (preference === 'reduce') {
    return true;
  }

  if (preference === 'no-preference') {
    return false;
  }

  if (typeof globalThis === 'undefined') {
    return false;
  }

  const media = globalThis.matchMedia;
  if (typeof media !== 'function') {
    return false;
  }

  try {
    return media.call(globalThis, REDUCED_MOTION_QUERY).matches;
  } catch {
    return false;
  }
}

/**
 * Resolves the animation duration for a named token.
 *
 * @param name - Duration token name.
 * @param reducedMotion - Whether reduced motion should be applied.
 * @returns Duration in milliseconds.
 */
export function getAnimationDuration(
  name: AnimationDurationName,
  reducedMotion: boolean = isReducedMotion(),
): number {
  if (reducedMotion) {
    return 0;
  }

  return animationTokens.duration[name];
}

/**
 * Resolves the animation easing curve for a named token.
 *
 * @param name - Easing token name.
 * @returns CSS easing curve.
 */
export function getAnimationEasing(name: AnimationEasingName): string {
  return animationTokens.easing[name];
}

/**
 * Resolves stagger delay in milliseconds.
 *
 * @param name - Stagger token name.
 * @param reducedMotion - Whether reduced motion should be applied.
 * @returns Delay in milliseconds.
 */
export function getStaggerDelay(name: StaggerStepName, reducedMotion: boolean = isReducedMotion()): number {
  if (reducedMotion) {
    return 0;
  }

  return animationTokens.stagger[name];
}

/**
 * Builds the shared transition object.
 *
 * @param duration - Duration token name.
 * @param easing - Easing token name.
 * @param delay - Optional delay token name.
 * @param reducedMotion - Whether reduced motion should be applied.
 * @returns Transition configuration.
 */
export function createTransition(
  duration: AnimationDurationName = 'normal',
  easing: AnimationEasingName = 'standard',
  delay: StaggerStepName = 'none',
  reducedMotion: boolean = isReducedMotion(),
): Readonly<Record<string, string | number | boolean | undefined>> {
  return Object.freeze({
    duration: getAnimationDuration(duration, reducedMotion) / 1000,
    ease: getAnimationEasing(easing),
    delay: getStaggerDelay(delay, reducedMotion) / 1000,
  });
}

/**
 * Creates a fade-in animation configuration.
 *
 * @param duration - Duration token name.
 * @param delay - Delay token name.
 * @param reducedMotion - Whether reduced motion should be applied.
 * @returns Animation state configuration.
 */
export function fadeIn(
  duration: AnimationDurationName = 'normal',
  delay: StaggerStepName = 'none',
  reducedMotion: boolean = isReducedMotion(),
): AnimationState {
  const transition = createTransition(duration, 'standard', delay, reducedMotion);

  return Object.freeze({
    initial: Object.freeze({ opacity: reducedMotion ? 1 : 0 }),
    animate: Object.freeze({ opacity: 1 }),
    transition,
  });
}

/**
 * Creates an upward slide-in animation configuration.
 *
 * @param duration - Duration token name.
 * @param delay - Delay token name.
 * @param reducedMotion - Whether reduced motion should be applied.
 * @returns Animation state configuration.
 */
export function moveUp(
  duration: AnimationDurationName = 'normal',
  delay: StaggerStepName = 'none',
  reducedMotion: boolean = isReducedMotion(),
): AnimationState {
  const transition = createTransition(duration, 'decelerate', delay, reducedMotion);

  return Object.freeze({
    initial: Object.freeze({ opacity: reducedMotion ? 1 : 0, y: reducedMotion ? 0 : 24 }),
    animate: Object.freeze({ opacity: 1, y: 0 }),
    transition,
  });
}

/**
 * Creates a blur-disperse animation configuration.
 *
 * @param duration - Duration token name.
 * @param delay - Delay token name.
 * @param reducedMotion - Whether reduced motion should be applied.
 * @returns Animation state configuration.
 */
export function blurDissipate(
  duration: AnimationDurationName = 'normal',
  delay: StaggerStepName = 'none',
  reducedMotion: boolean = isReducedMotion(),
): AnimationState {
  const transition = createTransition(duration, 'standard', delay, reducedMotion);

  return Object.freeze({
    initial: Object.freeze({ opacity: reducedMotion ? 1 : 0, filter: reducedMotion ? 'none' : 'blur(14px)' }),
    animate: Object.freeze({ opacity: 1, filter: 'blur(0px)' }),
    transition,
  });
}

/**
 * Creates a hover-scale animation configuration.
 *
 * @param scale - Hover scale factor.
 * @param reducedMotion - Whether reduced motion should be applied.
 * @returns Animation state configuration.
 */
export function hoverScale(scale: number = 1.02, reducedMotion: boolean = isReducedMotion()): AnimationState {
  return Object.freeze({
    initial: Object.freeze({ scale: 1 }),
    animate: Object.freeze({ scale: 1 }),
    whileHover: Object.freeze({ scale: reducedMotion ? 1 : scale }),
    transition: createTransition('fast', 'sharp', 'none', reducedMotion),
  });
}

/**
 * Creates a scroll-enter animation configuration.
 *
 * @param direction - Entry direction.
 * @param duration - Duration token name.
 * @param delay - Delay token name.
 * @param reducedMotion - Whether reduced motion should be applied.
 * @returns Animation state configuration.
 */
export function scrollIn(
  direction: 'up' | 'down' = 'up',
  duration: AnimationDurationName = 'normal',
  delay: StaggerStepName = 'none',
  reducedMotion: boolean = isReducedMotion(),
): AnimationState {
  const offset = direction === 'up' ? 24 : -24;
  const transition = createTransition(duration, 'decelerate', delay, reducedMotion);

  return Object.freeze({
    initial: Object.freeze({ opacity: reducedMotion ? 1 : 0, y: reducedMotion ? 0 : offset }),
    animate: Object.freeze({ opacity: 1, y: 0 }),
    transition,
    viewport: animationTokens.viewport,
  });
}

/**
 * Creates a page transition animation configuration.
 *
 * @param mode - Page transition mode.
 * @param reducedMotion - Whether reduced motion should be applied.
 * @returns Animation state configuration.
 */
export function pageTransition(
  mode: 'enter' | 'exit' = 'enter',
  reducedMotion: boolean = isReducedMotion(),
): AnimationState {
  if (mode === 'exit') {
    return Object.freeze({
      initial: Object.freeze({ opacity: 1, y: 0 }),
      animate: Object.freeze({ opacity: 1, y: 0 }),
      exit: Object.freeze({ opacity: 0, y: reducedMotion ? 0 : -12 }),
      transition: createTransition('slow', 'standard', 'none', reducedMotion),
    });
  }

  return Object.freeze({
    initial: Object.freeze({ opacity: reducedMotion ? 1 : 0, y: reducedMotion ? 0 : 12 }),
    animate: Object.freeze({ opacity: 1, y: 0 }),
    exit: Object.freeze({ opacity: 0, y: reducedMotion ? 0 : -12 }),
    transition: createTransition('slow', 'standard', 'none', reducedMotion),
  });
}

/**
 * Normalizes a breakpoint name into a stagger delay token for responsive sequencing.
 *
 * @param breakpoint - Layout breakpoint name.
 * @returns Stagger token name.
 */
export function staggerForBreakpoint(breakpoint: BreakpointName): StaggerStepName {
  switch (breakpoint) {
    case 'xs':
      return 'none';
    case 'sm':
      return 'xs';
    case 'md':
      return 'sm';
    case 'lg':
      return 'md';
    case 'xl':
      return 'lg';
    case '2xl':
      return 'lg';
    default: {
      const exhaustiveCheck: never = breakpoint;
      return exhaustiveCheck;
    }
  }
}

