import type { Article, AuthorProfile, ContentLayer, FooterLink, HeroContent } from './content';
import type { SiteConfig, Url } from './types';
import type { BreakpointName, CardElevation, Theme } from './theme';

/**
 * Layout section identifier.
 */
export type LayoutSectionKey =
  | 'topbar'
  | 'hero'
  | 'featured'
  | 'articleGrid'
  | 'detailHero'
  | 'authorCard'
  | 'cta'
  | 'footer';

/**
 * Supported anchor navigation target ids.
 */
export type AnchorTarget = `#${string}`;

/**
 * Layout container width token.
 */
export type ContentWidth = 'narrow' | 'standard' | 'wide';

/**
 * Semantic navigation item used by layout factories.
 */
export interface LayoutNavItem {
  /** Display label. */
  readonly label: string;
  /** Anchor or URL target. */
  readonly href: AnchorTarget | Url;
  /** Whether the item is the current section. */
  readonly active?: boolean;
}

/**
 * Section spacing configuration.
 */
export interface SectionSpacing {
  /** Top spacing class/token. */
  readonly top: string;
  /** Bottom spacing class/token. */
  readonly bottom: string;
}

/**
 * Layout block descriptor.
 */
export interface LayoutBlock {
  /** Stable block key. */
  readonly key: LayoutSectionKey;
  /** Semantic tag name. */
  readonly tag: 'header' | 'main' | 'section' | 'aside' | 'footer' | 'nav' | 'article';
  /** Optional id for anchor links. */
  readonly id?: string;
  /** Human readable label. */
  readonly ariaLabel?: string;
  /** Content width constraint. */
  readonly width: ContentWidth;
  /** Section spacing. */
  readonly spacing: SectionSpacing;
  /** Visual elevation used by cards inside the block. */
  readonly elevation?: CardElevation;
}

/**
 * Complete page layout blueprint.
 */
export interface PageLayoutBlueprint {
  /** Top-level site configuration. */
  readonly site: SiteConfig;
  /** Theme tokens used to guide sizing and spacing. */
  readonly theme: Theme;
  /** Navigation items including anchor targets. */
  readonly navigation: readonly LayoutNavItem[];
  /** Ordered blocks that compose the page. */
  readonly blocks: readonly LayoutBlock[];
  /** Anchor ids used for the page table of contents. */
  readonly anchors: readonly string[];
}

/**
 * Composed page shell output.
 */
export interface PageShell {
  /** Blueprint describing structure and semantic organization. */
  readonly blueprint: PageLayoutBlueprint;
  /** Content layer referenced by the shell. */
  readonly content: ContentLayer;
}

/**
 * Creates a stable top navigation with anchor navigation support.
 */
export function createTopbarNavigation(content: ContentLayer): readonly LayoutNavItem[] {
  const items: readonly LayoutNavItem[] = content.navigation.map((item) => ({
    label: item.label,
    href: item.href.startsWith('/') ? (`#${item.href.slice(1)}` as AnchorTarget) : item.href,
    active: item.href === '/'.concat(''),
  }));
  return items;
}

/**
 * Creates a default section spacing token pair.
 */
export function createSectionSpacing(top: string, bottom: string): SectionSpacing {
  return Object.freeze({ top, bottom });
}

/**
 * Creates a block descriptor.
 */
export function createLayoutBlock(params: {
  readonly key: LayoutSectionKey;
  readonly tag: LayoutBlock['tag'];
  readonly id?: string;
  readonly ariaLabel?: string;
  readonly width?: ContentWidth;
  readonly spacing?: SectionSpacing;
  readonly elevation?: CardElevation;
}): LayoutBlock {
  return Object.freeze({
    key: params.key,
    tag: params.tag,
    id: params.id,
    ariaLabel: params.ariaLabel,
    width: params.width ?? 'standard',
    spacing: params.spacing ?? createSectionSpacing('py-16', 'pb-16'),
    elevation: params.elevation,
  });
}

/**
 * Creates the full Apple-style page layout blueprint.
 */
export function createPageLayout(content: ContentLayer, theme: Theme): PageLayoutBlueprint {
  const navigation: readonly LayoutNavItem[] = createTopbarNavigation(content);
  const anchors: readonly string[] = ['home', 'articles', 'about', 'archive', 'contact'];
  const blocks: readonly LayoutBlock[] = [
    createLayoutBlock({ key: 'topbar', tag: 'header', id: 'site-header', ariaLabel: 'Site header', width: 'wide', spacing: createSectionSpacing('pt-6', 'pb-4') }),
    createLayoutBlock({ key: 'hero', tag: 'section', id: 'home', ariaLabel: 'Hero introduction', width: 'wide', spacing: createSectionSpacing('pt-12', 'pb-20') }),
    createLayoutBlock({ key: 'featured', tag: 'section', id: 'featured-articles', ariaLabel: 'Featured articles', width: 'standard', spacing: createSectionSpacing('py-14', 'pb-14'), elevation: 'sm' }),
    createLayoutBlock({ key: 'articleGrid', tag: 'main', id: 'articles', ariaLabel: 'Article grid', width: 'standard', spacing: createSectionSpacing('py-16', 'pb-20') }),
    createLayoutBlock({ key: 'detailHero', tag: 'article', id: 'article-hero', ariaLabel: 'Article detail header', width: 'narrow', spacing: createSectionSpacing('py-12', 'pb-12'), elevation: 'md' }),
    createLayoutBlock({ key: 'authorCard', tag: 'aside', id: 'author', ariaLabel: 'Author profile', width: 'narrow', spacing: createSectionSpacing('py-10', 'pb-10'), elevation: 'sm' }),
    createLayoutBlock({ key: 'cta', tag: 'section', id: 'subscribe', ariaLabel: 'Subscribe call to action', width: 'standard', spacing: createSectionSpacing('py-16', 'pb-16'), elevation: 'lg' }),
    createLayoutBlock({ key: 'footer', tag: 'footer', id: 'site-footer', ariaLabel: 'Site footer', width: 'wide', spacing: createSectionSpacing('pt-16', 'pb-10') }),
  ];
  return Object.freeze({ site: content.site, theme, navigation, blocks, anchors });
}

/**
 * Creates a complete shell object for rendering the page.
 */
export function createPageShell(content: ContentLayer, theme: Theme): PageShell {
  return Object.freeze({ blueprint: createPageLayout(content, theme), content });
}

/**
 * Creates a hero section composition descriptor.
 */
export function createHeroSection(hero: HeroContent): LayoutBlock {
  return createLayoutBlock({ key: 'hero', tag: 'section', id: 'home', ariaLabel: hero.title, width: 'wide', spacing: createSectionSpacing('pt-12', 'pb-20') });
}

/**
 * Creates a featured articles section descriptor.
 */
export function createFeaturedArticlesSection(): LayoutBlock {
  return createLayoutBlock({ key: 'featured', tag: 'section', id: 'featured-articles', ariaLabel: '精选文章', width: 'standard', spacing: createSectionSpacing('py-14', 'pb-14'), elevation: 'sm' });
}

/**
 * Creates an article grid section descriptor.
 */
export function createArticleGridSection(): LayoutBlock {
  return createLayoutBlock({ key: 'articleGrid', tag: 'main', id: 'articles', ariaLabel: '文章网格', width: 'standard', spacing: createSectionSpacing('py-16', 'pb-20') });
}

/**
 * Creates a detail header hero section descriptor.
 */
export function createDetailHeroSection(article: Article): LayoutBlock {
  return createLayoutBlock({ key: 'detailHero', tag: 'article', id: `article-${article.slug}`, ariaLabel: article.title, width: 'narrow', spacing: createSectionSpacing('py-12', 'pb-12'), elevation: 'md' });
}

/**
 * Creates an author card section descriptor.
 */
export function createAuthorCardSection(author: AuthorProfile): LayoutBlock {
  return createLayoutBlock({ key: 'authorCard', tag: 'aside', id: `author-${author.id}`, ariaLabel: author.name, width: 'narrow', spacing: createSectionSpacing('py-10', 'pb-10'), elevation: 'sm' });
}

/**
 * Creates a subscribe or call-to-action section descriptor.
 */
export function createCallToActionSection(label: string): LayoutBlock {
  return createLayoutBlock({ key: 'cta', tag: 'section', id: 'subscribe', ariaLabel: label, width: 'standard', spacing: createSectionSpacing('py-16', 'pb-16'), elevation: 'lg' });
}

/**
 * Creates a footer section descriptor.
 */
export function createFooterSection(_links: readonly FooterLink[]): LayoutBlock {
  return createLayoutBlock({ key: 'footer', tag: 'footer', id: 'site-footer', ariaLabel: 'Footer', width: 'wide', spacing: createSectionSpacing('pt-16', 'pb-10') });
}

/**
 * Resolves a content width class/token.
 */
export function resolveContentWidth(width: ContentWidth): string {
  switch (width) {
    case 'narrow':
      return 'max-w-3xl';
    case 'standard':
      return 'max-w-6xl';
    case 'wide':
      return 'max-w-7xl';
  }
}

/**
 * Resolves a responsive breakpoint container string.
 */
export function resolveContainerClass(_breakpoint: BreakpointName): string {
  return 'mx-auto w-full px-6 sm:px-8 lg:px-10';
}

/**
 * Builds the semantic page section order for navigation and rendering.
 */
export function buildSemanticSectionOrder(): readonly LayoutSectionKey[] {
  return ['topbar', 'hero', 'featured', 'articleGrid', 'detailHero', 'authorCard', 'cta', 'footer'];
}

