import { strict as assert } from 'node:assert';

import {
  articles,
  author,
  content,
  featuredArticles,
  footerLinks,
  getArticleBySlug,
  getFeaturedArticles,
  getNavigation,
  getRecommendedArticles,
  hero,
  navigation,
  site,
} from './content';
import type {
  Article,
  AuthorProfile,
  ContentLayer,
  FooterLink,
  HeroContent,
} from './content';
import type {
  ArticleStatus,
  EntityId,
  FooterLinkGroup,
  Locale,
  NavigationItem,
  RoutePath,
  SectionId,
  SiteConfig,
  Url,
} from './types';

/**
 * Asserts a value against a compile-time type contract.
 *
 * @template T - Expected type.
 * @param value - Value to validate.
 * @returns The same value, preserving its type.
 */
function expectType<T>(value: T): T {
  return value;
}

/**
 * Creates a minimal author profile for tests.
 *
 * @param id - Author identifier.
 * @param name - Author name.
 * @returns Author profile.
 */
function createAuthor(id: EntityId, name: string): AuthorProfile {
  return {
    id,
    name,
    bio: `${name} bio`,
    avatarUrl: 'https://example.com/avatar.png',
  };
}

/**
 * Creates a deterministic article for tests.
 *
 * @param overrides - Partial article overrides.
 * @returns Article.
 */
function createArticle(overrides: Partial<Article> = {}): Article {
  return {
    id: 'article-1',
    slug: 'article-1',
    title: 'Article 1',
    excerpt: 'Excerpt 1',
    content: 'Content 1',
    coverImageUrl: 'https://example.com/cover.png',
    publishedAt: '2024-01-01',
    status: 'published',
    featured: false,
    readingTimeMinutes: 5,
    summary: 'Summary 1',
    author: createAuthor('author-1', 'Author 1'),
    tags: ['tag-a'],
    relatedArticleIds: ['article-2'],
    ...overrides,
  };
}

/**
 * Runs the content layer assertions.
 */
function run(): void {
  expectType<SiteConfig>(site);
  assert.equal(site.name.length > 0, true);
  assert.equal(site.tagline.length > 0, true);
  assert.equal(site.description.length > 0, true);
  assert.equal(site.siteUrl.length > 0, true);
  assert.equal(site.logoUrl.length > 0, true);
  assert.equal(site.ogImageUrl.length > 0, true);
  assert.equal(site.copyright.length > 0, true);
  assert.deepEqual(site, {
    ...site,
  });
  assert.ok((['zh-CN', 'en-US', 'ja-JP', 'ko-KR', 'fr-FR', 'de-DE', 'es-ES'] as readonly Locale[]).includes(site.locale));

  expectType<ContentLayer>(content);
  assert.deepEqual(content.site, site);
  assert.deepEqual(content.hero, hero);
  assert.deepEqual(content.navigation, navigation);
  assert.deepEqual(content.articles, articles);
  assert.deepEqual(content.featuredArticles, featuredArticles);
  assert.deepEqual(content.author, author);
  assert.deepEqual(content.footerLinks, footerLinks);

  expectType<HeroContent>(hero);
  assert.equal(hero.title.length > 0, true);
  assert.equal(hero.description.length > 0, true);
  assert.equal(hero.primaryActionLabel.length > 0, true);
  assert.equal(hero.secondaryActionLabel.length > 0, true);

  expectType<readonly NavigationItem[]>(navigation);
  assert.equal(navigation.length > 0, true);
  assert.ok(navigation.every((item: NavigationItem) => item.label.length > 0));

  expectType<readonly FooterLink[]>(footerLinks);
  assert.ok(footerLinks.every((link: FooterLink) => link.label.length > 0));

  const featured = getFeaturedArticles();
  expectType<readonly Article[]>(featured);
  assert.deepEqual(featured, featuredArticles);
  assert.ok(featured.every((article: Article) => article.featured));

  const bySlug = getArticleBySlug('designing-better-reading-experiences');
  assert.equal(bySlug?.slug, 'designing-better-reading-experiences');
  assert.equal(getArticleBySlug(''), undefined);
  assert.equal(getArticleBySlug(null), undefined);
  assert.equal(getArticleBySlug(undefined), undefined);
  assert.equal(getArticleBySlug('missing-slug'), undefined);
  assert.equal(getArticleBySlug(' designing-better-reading-experiences '), bySlug);

  const navFromLocale = getNavigation('zh-CN');
  expectType<readonly NavigationItem[]>(navFromLocale);
  assert.deepEqual(navFromLocale, navigation);

  const recommended = getRecommendedArticles('designing-better-reading-experiences', 3);
  expectType<readonly Article[]>(recommended);
  assert.equal(recommended.length <= 3, true);
  assert.equal(recommended.some((article: Article) => article.slug === 'designing-better-reading-experiences'), false);

  const recommendedDefault = getRecommendedArticles('designing-better-reading-experiences');
  assert.equal(recommendedDefault.length <= 3, true);

  const recommendedInvalidLimit = getRecommendedArticles('designing-better-reading-experiences', 0);
  assert.equal(recommendedInvalidLimit.length <= 3, true);

  const recommendedFromMissing = getRecommendedArticles('missing-slug', 2);
  assert.equal(recommendedFromMissing.length <= 2, true);
  assert.ok(recommendedFromMissing.every((article: Article) => article.slug !== 'missing-slug'));

  const customArticles: readonly Article[] = [
    createArticle({ id: 'a-3', slug: 'c', publishedAt: '2024-03-01', title: 'C' }),
    createArticle({ id: 'a-1', slug: 'a', publishedAt: '2024-01-01', title: 'A' }),
    createArticle({ id: 'a-2', slug: 'b', publishedAt: '2024-02-01', title: 'B' }),
  ];

  const sortedByPublishedAtDesc = [...customArticles].sort((left: Article, right: Article) => right.publishedAt.localeCompare(left.publishedAt));
  assert.deepEqual(sortedByPublishedAtDesc.map((article: Article) => article.slug), ['c', 'b', 'a']);

  const emptyArticles: readonly Article[] = [];
  assert.deepEqual(emptyArticles, []);
  assert.deepEqual(getFeaturedArticles().filter((article: Article) => article.featured), featuredArticles);

  assert.ok(['draft', 'published', 'archived'] as readonly ArticleStatus[]);
  assert.ok((['header', 'footer', 'social', 'legal'] as readonly FooterLinkGroup[]).length > 0);
  assert.ok((['/', '/articles', '/about'] as readonly RoutePath[]).length > 0);
  assert.ok((['home', 'articles', 'about', 'contact'] as readonly SectionId[]).length > 0);
  assert.ok(('https://example.com' as Url).length > 0);
}

run();

export {};

