/**
 * Assert helper that throws when the condition is false.
 *
 * @param condition - Condition expected to be true.
 * @param message - Error message for failed assertions.
 */
function assert(condition: boolean, message: string): void {
  if (!condition) {
    throw new Error(message);
  }
}

/**
 * Compares two values using strict equality.
 *
 * @param actual - Actual value.
 * @param expected - Expected value.
 * @param label - Assertion label.
 */
function expectEqual(actual: unknown, expected: unknown, label: string): void {
  assert(Object.is(actual, expected), `${label}: expected ${String(expected)}, received ${String(actual)}`);
}

/**
 * Verifies that a string contains the expected substring.
 *
 * @param value - String to inspect.
 * @param substring - Required substring.
 * @param label - Assertion label.
 */
function expectIncludes(value: string, substring: string, label: string): void {
  assert(value.includes(substring), `${label}: expected ${JSON.stringify(value)} to include ${JSON.stringify(substring)}`);
}

/**
 * Creates a compact snapshot of the theme token shape.
 *
 * @returns A serializable summary of theme-relevant tokens.
 */
function getThemeSnapshot(): Record<string, unknown> {
  return {
    colors: {
      background: theme.colors.background,
      foreground: theme.colors.foreground,
      accent: theme.colors.accent,
      border: theme.colors.border,
      overlay: theme.colors.overlay,
    },
    spacing: {
      0: theme.spacing[0],
      1: theme.spacing[1],
      2: theme.spacing[2],
      3: theme.spacing[3],
      4: theme.spacing[4],
      6: theme.spacing[6],
      8: theme.spacing[8],
      12: theme.spacing[12],
      16: theme.spacing[16],
      24: theme.spacing[24],
      32: theme.spacing[32],
      40: theme.spacing[40],
      48: theme.spacing[48],
      64: theme.spacing[64],
    },
    breakpoints: theme.breakpoints,
    typography: theme.typography,
    radii: theme.radii,
    shadows: theme.shadows,
  };
}

