  expectEqual(theme.colors.background.elevated, '#ffffff', 'background elevated');
  expectEqual(theme.colors.foreground.primary, '#111111', 'foreground primary');
  expectEqual(theme.colors.foreground.secondary, '#6e6e73', 'foreground secondary');
  expectEqual(theme.colors.accent.primary, '#0071e3', 'accent primary');
  expectEqual(theme.colors.accent.primaryHover, '#0058b0', 'accent primary hover');
  expectEqual(theme.colors.border.default, 'rgba(0, 0, 0, 0.12)', 'border default');
  expectEqual(theme.spacing[0], '0px', 'spacing 0');
  expectEqual(theme.spacing[4], '16px', 'spacing 4');
  expectEqual(theme.spacing[8], '32px', 'spacing 8');
  expectEqual(theme.spacing[16], '64px', 'spacing 16');
  expectEqual(theme.breakpoints.sm, '640px', 'breakpoint sm');
  expectEqual(theme.breakpoints.md, '768px', 'breakpoint md');
  expectEqual(theme.breakpoints.lg, '1024px', 'breakpoint lg');
  expectEqual(theme.breakpoints.xl, '1280px', 'breakpoint xl');
  expectEqual(theme.typography.display.fontSize, '4.5rem', 'typography display size');
  expectEqual(theme.typography.display.lineHeight, 1.05, 'typography display line height');
  expectEqual(theme.typography.h1.fontWeight, 700, 'typography h1 weight');
  expectEqual(theme.typography.overline.textTransform, 'uppercase', 'typography overline transform');
