/**
 * Validates that the animation preset tokens are predictable.
 */
function testAnimationTokens(): void {
  expectEqual(animationTokens.motionPreference, 'system', 'motion preference default');
  expectEqual(animationTokens.duration.fast, 180, 'duration fast');
  expectEqual(animationTokens.duration.normal, 280, 'duration normal');
  expectEqual(animationTokens.duration.slow, 420, 'duration slow');
  expectEqual(animationTokens.duration.slower, 560, 'duration slower');
  expectEqual(animationTokens.easing.standard, 'cubic-bezier(0.2, 0, 0, 1)', 'easing standard');
  expectEqual(animationTokens.easing.decelerate, 'cubic-bezier(0, 0, 0.2, 1)', 'easing decelerate');
  expectEqual(animationTokens.easing.accelerate, 'cubic-bezier(0.4, 0, 1, 1)', 'easing accelerate');
  expectEqual(animationTokens.easing.sharp, 'cubic-bezier(0.4, 0, 0.6, 1)', 'easing sharp');
  expectEqual(animationTokens.stagger.none, 0, 'stagger none');
  expectEqual(animationTokens.stagger.xs, 40, 'stagger xs');
  expectEqual(animationTokens.stagger.sm, 80, 'stagger sm');
  expectEqual(animationTokens.stagger.md, 120, 'stagger md');
  expectEqual(animationTokens.stagger.lg, 160, 'stagger lg');
  expectEqual(animationTokens.viewport.amount, 0.25, 'viewport amount');
