/**
 * Validates reduced-motion resolution and the resulting transition output.
 */
function testReducedMotionBranching(): void {
  const reduced: AnimationState = {
    initial: { opacity: 0, y: 0 },
    animate: { opacity: 1, y: 0 },
    transition: {
      duration: animationTokens.duration.fast,
      ease: animationTokens.easing.standard,
    },
  };

  const standard: AnimationState = {
    initial: { opacity: 0, y: 16 },
    animate: { opacity: 1, y: 0 },
    exit: { opacity: 0, y: -8 },
    transition: {
      duration: animationTokens.duration.normal,
      ease: animationTokens.easing.decelerate,
      type: 'tween',
    },
    viewport: animationTokens.viewport,
    whileHover: { scale: 1.02 },
  };

  expectEqual(reduced.initial.y, 0, 'reduced initial y');
  expectEqual(reduced.animate.y, 0, 'reduced animate y');
  expectEqual(reduced.transition.duration, animationTokens.duration.fast, 'reduced duration');
  expectEqual(standard.initial.y, 16, 'standard initial y');
  expectEqual(standard.exit?.y, -8, 'standard exit y');
  expectEqual(standard.transition.duration, animationTokens.duration.normal, 'standard duration');
  expectEqual(standard.transition.type, 'tween', 'standard transition type');
  expectEqual(standard.viewport?.once, true, 'standard viewport once');
  expectEqual(standard.whileHover?.scale, 1.02, 'standard hover scale');
}

/**
 * Validates exported token unions remain usable with the current system.
 */
function testTokenUnions(): void {
  const modes: ReadonlyArray<ThemeMode> = ['light', 'dark', 'system'];
  const breakpoints: ReadonlyArray<BreakpointName> = ['xs', 'sm', 'md', 'lg', 'xl', '2xl'];
  const roles: ReadonlyArray<TextStyleRole> = ['title', 'subtitle', 'body', 'caption', 'overline'];
  const elevations: ReadonlyArray<CardElevation> = ['none', 'sm', 'md', 'lg'];

  expectEqual(modes.length, 3, 'theme modes length');
  expectEqual(breakpoints[3], 'lg', 'breakpoint label');
  expectEqual(roles[0], 'title', 'text role title');
  expectEqual(elevations[2], 'md', 'elevation md');
}

/**
 * Executes all theme and animation token assertions.
 */
function main(): void {
  testThemeTokens();
  testAnimationTokens();
  testReducedMotionBranching();
  testTokenUnions();

  const snapshot: Record<string, unknown> = getThemeSnapshot();
  expectIncludes(JSON.stringify(snapshot), 'background', 'snapshot contains background');
  expectIncludes(JSON.stringify(snapshot), 'display', 'snapshot contains display typography');
}

main();
